ALTER TABLE public.quote_relative_schedules ADD COLUMN stage_offsets jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN allocation_offsets jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE OR REPLACE FUNCTION public.pm_relative_offset(_date date) RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _date>=date '2000-01-03' THEN (SELECT count(*)::integer-1 FROM generate_series(date '2000-01-03'::timestamp,_date::timestamp,interval '1 day') d WHERE extract(isodow FROM d)<6) ELSE -(SELECT count(*)::integer-1 FROM generate_series(_date::timestamp,date '2000-01-03'::timestamp,interval '1 day') d WHERE extract(isodow FROM d)<6) END $$;
CREATE OR REPLACE FUNCTION public.pm_relative_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE q uuid;
BEGIN q:=NEW.quote_id;
UPDATE quote_relative_schedules SET stage_offsets=coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'start',pm_relative_offset(start_date),'duration',pm_relative_offset(end_date)-pm_relative_offset(start_date)+1) ORDER BY id) FROM quote_stages WHERE quote_id=q),'[]'::jsonb),allocation_offsets=coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'stage_id',stage_id,'start',pm_relative_offset(start_date),'duration',pm_relative_offset(end_date)-pm_relative_offset(start_date)+1) ORDER BY id) FROM quote_allocations WHERE quote_id=q),'[]'::jsonb) WHERE quote_id=q;
RETURN NEW; END $$;
CREATE TRIGGER quote_stage_relative_offsets AFTER INSERT OR UPDATE OF start_date,end_date ON public.quote_stages FOR EACH ROW EXECUTE FUNCTION public.pm_relative_sync();
CREATE TRIGGER quote_allocation_relative_offsets AFTER INSERT OR UPDATE OF start_date,end_date ON public.quote_allocations FOR EACH ROW EXECUTE FUNCTION public.pm_relative_sync();
CREATE OR REPLACE FUNCTION public.pm_calendar_shift(_date date,_days integer) RETURNS date LANGUAGE plpgsql STABLE SET search_path=public AS $$
DECLARE d date:=_date; left_days integer:=abs(_days); direction integer:=CASE WHEN _days<0 THEN -1 ELSE 1 END; i integer:=0;
BEGIN IF abs(_days)>36600 OR _date IS NULL THEN RAISE EXCEPTION 'gantt.schedule.invalidRange'; END IF;
WHILE extract(isodow FROM d)>5 OR EXISTS(SELECT 1 FROM holidays WHERE data=d) LOOP d:=d+direction; i:=i+1; IF i>36600 THEN RAISE EXCEPTION 'gantt.schedule.invalidRange'; END IF; END LOOP;
WHILE left_days>0 LOOP d:=d+direction; IF extract(isodow FROM d)<6 AND NOT EXISTS(SELECT 1 FROM holidays WHERE data=d) THEN left_days:=left_days-1; END IF; END LOOP;
RETURN d; END $$;
CREATE OR REPLACE FUNCTION public.pm_quote_conversion_preview(_quote uuid,_start date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE state jsonb; start_day date; dates jsonb; allocations jsonb; revision_data jsonb;
BEGIN IF auth.uid() IS NULL OR NOT is_psa_staff() THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
state:=pm_gantt_state('quote',_quote); start_day:=pm_calendar_shift(_start,0);
IF NOT EXISTS(SELECT 1 FROM fee_proposals WHERE id=_quote AND pm_project_id IS NULL) THEN RAISE EXCEPTION 'gantt.schedule.locked'; END IF;
IF NOT EXISTS(SELECT 1 FROM quote_relative_schedules WHERE quote_id=_quote) THEN RAISE EXCEPTION 'gantt.relative.required'; END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'parent_stage_id',s.parent_stage_id,'start_date',CASE WHEN s.stage_kind='retainer_monthly' THEN date_trunc('month',start_day)::date ELSE pm_calendar_shift(start_day,pm_relative_offset(s.start_date)) END,'end_date',CASE WHEN s.stage_kind='retainer_monthly' THEN (date_trunc('month',start_day)+make_interval(months=>greatest(1,coalesce(s.retainer_months,1)))-interval '1 day')::date ELSE pm_calendar_shift(start_day,pm_relative_offset(s.end_date)) END,'stage_kind',s.stage_kind,'retainer_months',s.retainer_months,'retainer_monthly_amount',s.retainer_monthly_amount) ORDER BY s.sort_order,s.id),'[]'::jsonb) INTO dates FROM quote_stages s WHERE quote_id=_quote;
SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'stage_id',a.stage_id,'resource_id',a.resource_id,'resource_name',r.name,'hours_per_day',a.hours_per_day,'start_date',pm_calendar_shift(start_day,pm_relative_offset(a.start_date)),'end_date',pm_calendar_shift(start_day,pm_relative_offset(a.end_date))) ORDER BY a.id),'[]'::jsonb) INTO allocations FROM quote_allocations a JOIN pm_resources r ON r.id=a.resource_id WHERE a.quote_id=_quote;
revision_data:=jsonb_build_object('schedule',state->>'revision','payments',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM quote_payment_schedule_items p WHERE quote_id=_quote),'[]'::jsonb),'external',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY id) FROM quote_external_services e WHERE quote_id=_quote),'[]'::jsonb),'start',start_day);
RETURN jsonb_build_object('start_date',start_day,'stages',dates,'allocations',allocations,'dependencies',state->'dependencies','revision',md5(revision_data::text)); END $$;
REVOKE ALL ON FUNCTION public.pm_quote_conversion_preview(uuid,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pm_quote_conversion_preview(uuid,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.pm_convert_relative_quote(_quote uuid,_start date,_revision text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE q fee_proposals; preview jsonb; project_id_new uuid; baseline uuid; stage_map jsonb:='{}'; payment_map jsonb:='{}'; group_map jsonb:='{}'; s quote_stages; a quote_allocations; p quote_payment_schedule_items; e quote_external_services; live_id uuid; child_id uuid; parent_id uuid; group_id uuid; bounds jsonb; bstart date; bend date; month_start date; month_end date; m integer; internal_fee numeric; external_fee numeric; multiplier numeric; stage_count integer:=0; allocation_count integer:=0; dependency_count integer:=0; external_count integer:=0; d quote_stage_dependencies; cols text; vals text; payload jsonb;
BEGIN
IF auth.uid() IS NULL OR NOT is_psa_staff() OR NOT has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
IF NOT pg_try_advisory_xact_lock(hashtextextended('gantt:quote:'||_quote::text,0)) THEN RAISE EXCEPTION 'gantt.schedule.busy'; END IF;
LOCK TABLE fee_proposals,quote_stages,quote_allocations,quote_stage_dependencies,quote_payment_schedule_items,quote_external_services IN SHARE ROW EXCLUSIVE MODE;
SELECT * INTO q FROM fee_proposals WHERE id=_quote FOR UPDATE;
IF NOT FOUND OR q.quote_status<>'approved' THEN RAISE EXCEPTION 'gantt.relative.approvedRequired'; END IF;
IF q.pm_project_id IS NOT NULL THEN RETURN jsonb_build_object('id',q.pm_project_id,'alreadyExisted',true,'stagesCopied',0,'dependenciesCopied',0,'allocationsCopied',0,'allocationsSkipped',0,'externalCopied',0); END IF;
preview:=pm_quote_conversion_preview(_quote,_start);
IF preview->>'revision' IS DISTINCT FROM _revision THEN RAISE EXCEPTION 'gantt.schedule.stale'; END IF;
multiplier:=coalesce(nullif(q.pricing_multiplier,0),1);
SELECT coalesce(sum(CASE WHEN coalesce(nullif(s.sale_source,''),q.fee_source_mode,'allocation')='budget' THEN coalesce(s.budget,0) ELSE coalesce((SELECT sum((pm_relative_offset(a.end_date)-pm_relative_offset(a.start_date)+1)*a.hours_per_day*a.sale_rate_snapshot) FROM quote_allocations a WHERE a.stage_id=s.id),0) END),0)*multiplier INTO internal_fee FROM quote_stages s WHERE s.quote_id=_quote AND NOT EXISTS(SELECT 1 FROM quote_stages c WHERE c.parent_stage_id=s.id);
SELECT coalesce(sum(sale_price*quantity),0)*multiplier INTO external_fee FROM quote_external_services WHERE quote_id=_quote;
INSERT INTO pm_projects(name,status,start_date,company_id,account_id,quote_id,opportunity_id,notes,sold_fee,sold_internal_fee,sold_external_fee,sold_pricing_multiplier,sold_at) VALUES(q.titulo,'active',(preview->>'start_date')::date,q.company_id,q.account_id,q.id,q.opportunity_id,'Created from approved proposal',internal_fee+external_fee,internal_fee,external_fee,multiplier,now()) RETURNING id INTO project_id_new;
FOR s IN SELECT * FROM quote_stages WHERE quote_id=_quote ORDER BY sort_order,id LOOP
SELECT value INTO bounds FROM jsonb_array_elements(preview->'stages') WHERE value->>'id'=s.id::text;
bstart:=(bounds->>'start_date')::date; bend:=(bounds->>'end_date')::date; live_id:=gen_random_uuid();
INSERT INTO pm_stages(id,project_id,name,start_date,end_date,color,sort_order,budget,stage_kind,billing_model,retainer_monthly_amount,retainer_anchor_month,retainer_months,retainer_capacity_hours_per_month,retainer_review_months,is_fee_only,is_self,children_bill_independently,is_milestone,bill_to_client,markup_pct,source_quote_stage_id) VALUES(live_id,project_id_new,s.name,bstart,bend,s.color,s.sort_order,s.budget,s.stage_kind,s.billing_model,s.retainer_monthly_amount,CASE WHEN s.stage_kind='retainer_monthly' THEN bstart ELSE s.retainer_anchor_month END,s.retainer_months,s.retainer_capacity_hours_per_month,s.retainer_review_months,s.is_fee_only,s.is_self,s.children_bill_independently,s.is_milestone,s.bill_to_client,s.markup_pct,s.id);
stage_map:=stage_map||jsonb_build_object(s.id::text,live_id); stage_count:=stage_count+1;
IF s.stage_kind='retainer_monthly' THEN
FOR m IN 0..greatest(0,coalesce(s.retainer_months,1)-1) LOOP
month_start:=(bstart+make_interval(months=>m))::date; month_end:=(month_start+interval '1 month'-interval '1 day')::date;
INSERT INTO pm_stages(project_id,parent_stage_id,name,start_date,end_date,color,sort_order,budget,stage_kind,billing_model,retainer_capacity_hours_per_month,is_fee_only) VALUES(project_id_new,live_id,to_char(month_start,'YYYY-MM')||' — '||s.name,month_start,month_end,s.color,s.sort_order*1000+m+1,s.retainer_monthly_amount,'retainer_month','stage',s.retainer_capacity_hours_per_month,s.is_fee_only) RETURNING id INTO child_id;
FOR a IN SELECT * FROM quote_allocations WHERE stage_id=s.id LOOP INSERT INTO pm_allocations(stage_id,resource_id,start_date,end_date,hours_per_day,allocation_percentage,status,source_quote_allocation_id) VALUES(child_id,a.resource_id,month_start,month_end,a.hours_per_day,a.allocation_percentage,'committed',a.id); allocation_count:=allocation_count+1; END LOOP;
END LOOP; END IF;
END LOOP;
FOR s IN SELECT * FROM quote_stages WHERE quote_id=_quote AND parent_stage_id IS NOT NULL LOOP UPDATE pm_stages SET parent_stage_id=(stage_map->>s.parent_stage_id::text)::uuid WHERE id=(stage_map->>s.id::text)::uuid; END LOOP;
FOR a IN SELECT a.* FROM quote_allocations a JOIN quote_stages s ON s.id=a.stage_id WHERE a.quote_id=_quote AND s.stage_kind<>'retainer_monthly' LOOP
SELECT value INTO bounds FROM jsonb_array_elements(preview->'allocations') WHERE value->>'id'=a.id::text;
INSERT INTO pm_allocations(stage_id,resource_id,start_date,end_date,hours_per_day,allocation_percentage,status,source_quote_allocation_id) VALUES((stage_map->>a.stage_id::text)::uuid,a.resource_id,(bounds->>'start_date')::date,(bounds->>'end_date')::date,a.hours_per_day,a.allocation_percentage,'committed',a.id); allocation_count:=allocation_count+1; END LOOP;
FOR d IN SELECT * FROM quote_stage_dependencies WHERE quote_id=_quote LOOP INSERT INTO pm_stage_dependencies(predecessor_id,successor_id,type,lag_days,source_quote_dependency_id) VALUES((stage_map->>d.predecessor_stage_id::text)::uuid,(stage_map->>d.successor_stage_id::text)::uuid,d.type::text::pm_dep_type,d.lag_days,d.id); dependency_count:=dependency_count+1; END LOOP;
FOR e IN SELECT * FROM quote_external_services WHERE quote_id=_quote LOOP INSERT INTO pm_materials(project_id,description,supplier_id,quantity,unit_cost,purchase_price,markup_type,markup_value,sale_price,sale_price_manual,status,notes,source_quote_external_service_id) VALUES(project_id_new,e.description,e.supplier_id,e.quantity,e.unit_cost,e.purchase_price,e.markup_type::text::pm_markup_type,e.markup_value,e.sale_price,e.sale_price_manual,e.status::text::pm_external_service_status,e.notes,e.id); external_count:=external_count+1; END LOOP;
INSERT INTO pm_project_contract_baseline(project_id,quote_id,total_fee,total_internal_fee,total_external_fee,pricing_multiplier,quote_title,quote_number) VALUES(project_id_new,_quote,internal_fee+external_fee,internal_fee,external_fee,multiplier,q.titulo,q.proposal_number) RETURNING id INTO baseline;
FOR s IN SELECT * FROM quote_stages WHERE quote_id=_quote LOOP SELECT value INTO bounds FROM jsonb_array_elements(preview->'stages') WHERE value->>'id'=s.id::text; INSERT INTO pm_project_contract_baseline_stages(baseline_id,live_stage_id,name,parent_name,start_date,end_date,budget,billing_model,stage_kind,sort_order) VALUES(baseline,(stage_map->>s.id::text)::uuid,s.name,(SELECT name FROM quote_stages WHERE id=s.parent_stage_id),(bounds->>'start_date')::date,(bounds->>'end_date')::date,s.budget,s.billing_model,s.stage_kind,s.sort_order); END LOOP;
FOR p IN SELECT * FROM quote_payment_schedule_items WHERE quote_id=_quote ORDER BY sort_order,id LOOP
INSERT INTO pm_project_contract_baseline_payments(baseline_id,label,trigger_type,amount,expected_invoice_date,expected_payment_date,stage_name,sort_order) VALUES(baseline,p.label,p.trigger_type::text,p.amount_value,p.expected_invoice_date,p.expected_payment_date,(SELECT name FROM quote_stages WHERE id=p.stage_id),p.sort_order);
live_id:=gen_random_uuid(); group_id:=NULL; IF p.invoice_group_id IS NOT NULL THEN group_id:=coalesce((group_map->>p.invoice_group_id::text)::uuid,gen_random_uuid()); group_map:=group_map||jsonb_build_object(p.invoice_group_id::text,group_id); END IF;
payload:=to_jsonb(p)||jsonb_build_object('id',live_id,'project_id',project_id_new,'entity_id','00000000-0000-4000-a000-000000000001','stage_id',stage_map->>p.stage_id::text,'invoice_group_id',group_id,'linked_payment_item_id',NULL,'source_quote_payment_item_id',p.id,'created_at',now(),'updated_at',now());
SELECT string_agg(quote_ident(column_name),',' ORDER BY ordinal_position),string_agg('x.'||quote_ident(column_name),',' ORDER BY ordinal_position) INTO cols,vals FROM information_schema.columns WHERE table_schema='public' AND table_name='pm_payment_schedule_items' AND payload ? column_name;
EXECUTE format('INSERT INTO public.pm_payment_schedule_items(%s) SELECT %s FROM jsonb_populate_record(NULL::public.pm_payment_schedule_items,$1) x',cols,vals) USING payload;
payment_map:=payment_map||jsonb_build_object(p.id::text,live_id); END LOOP;
FOR p IN SELECT * FROM quote_payment_schedule_items WHERE quote_id=_quote AND linked_payment_item_id IS NOT NULL LOOP UPDATE pm_payment_schedule_items SET linked_payment_item_id=(payment_map->>p.linked_payment_item_id::text)::uuid WHERE id=(payment_map->>p.id::text)::uuid; END LOOP;
UPDATE fee_proposals SET pm_project_id=project_id_new WHERE id=_quote;
IF q.opportunity_id IS NOT NULL THEN UPDATE crm_opportunities SET stage='won' WHERE id=q.opportunity_id; END IF;
RETURN jsonb_build_object('id',project_id_new,'alreadyExisted',false,'stagesCopied',stage_count,'dependenciesCopied',dependency_count,'allocationsCopied',allocation_count,'allocationsSkipped',0,'externalCopied',external_count);
END $$;
REVOKE ALL ON FUNCTION public.pm_convert_relative_quote(uuid,date,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.pm_convert_relative_quote(uuid,date,text) TO authenticated;
COMMENT ON COLUMN public.quote_relative_schedules.stage_offsets IS 'Explicit weekday offsets and inclusive durations; maintained with relative quote edits.';
COMMENT ON FUNCTION public.pm_convert_relative_quote(uuid,date,text) IS 'Admin-only atomic idempotent conversion bound to exact preview revision; original linked live projects cannot be re-dated.';